var d = tree.root.get_node("/root/AttackAssignmentDialog")
var wl = d.get_node("Content/WeaponList")
var tl = d.get_node("Content/TargetList")
if wl.item_count == 0 or tl.item_count == 0:
	return false
var want = 0
for i in range(wl.item_count):
	if str(wl.get_item_text(i)).begins_with("Choppa"):
		want = i
		break
wl.select(want)
wl.item_selected.emit(want)
tl.select(0)
tl.item_selected.emit(0)
return true

var b = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightResolutionDock/DockFastButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false

